<article class="hs-martyr"><a href="<?= e(url('profile',['id'=>$m['id']])) ?>"><div class="hs-martyr-photo"><?php if($m['cover']): ?><img loading="lazy" src="<?= e(url('media',['id'=>$m['cover']['id']])) ?>" width="400" height="500" alt="<?= e($m['title']) ?>"><?php else: ?><span aria-hidden="true">ن</span><?php endif ?></div><h3>شهید <?= e($m['title']) ?></h3><?php if($m['card_city']||$m['topics']): ?><p class="hs-martyr-meta"><?= e(implode(' · ',array_filter([$m['card_city'],implode('، ',$m['topics'])]))) ?></p><?php endif ?><span>مشاهده ←</span></a></article>